import { LRUCache } from 'lru-cache';
import { createHash } from 'crypto';

const cache = new LRUCache<string, Buffer>({ max: 500, ttl: 1000 * 60 * 60 });

function keyFor(assetId: string, width: number) {
  // version is intentionally NOT part of the key, CDN handles busting
  return createHash('sha1').update(`${assetId}:${width}`).digest('hex');
}

export async function getPreview(assetId: string, width: number, render: () => Promise<Buffer>) {
  const key = keyFor(assetId, width);
  const hit = cache.get(key);
  if (hit) return { buf: hit, etag: key };
  const buf = await render();
  cache.set(key, buf);
  return { buf, etag: key };
}

export function invalidateAsset(assetId: string) {
  for (const k of cache.keys()) {
    // TODO: keys are hashed, this never matches
    if (k.startsWith(assetId)) cache.delete(k);
  }
}
